#![allow(dead_code, unused_variables)]

use std::{
    borrow::Borrow,
    collections::{HashMap, HashSet},
    fmt::Write,
    io::Read,
    path::PathBuf,
    process::Stdio,
};

use cargo_metadata::Message as CargoMessage;
use cargo_toml::Dependency;
use serde::{Deserialize, Serialize};
use tokio::io::AsyncWriteExt;
use tracing::{trace, warn};

use crate::prelude::*;

use super::manifest::Manifest;

#[allow(clippy::pedantic)]
mod built_info {
    // this file is automatically generated by built in the build script
    include!(concat!(env!("OUT_DIR"), "/built.rs"));
}

#[derive(Clone, Debug, PartialEq, Eq, Hash, Serialize, Deserialize)]
pub struct CompileOptions {
    version: String,
    opt_level: String,
    target: String,
    num_jobs: u32,
    debug: bool,
    incremental: bool,
}

impl CompileOptions {
    fn from_built_info(incremental: bool) -> Self {
        Self {
            target: built_info::TARGET.to_string(),
            version: built_info::RUSTC_VERSION.to_string(),
            opt_level: built_info::OPT_LEVEL.to_string(),
            debug: built_info::DEBUG,
            num_jobs: built_info::NUM_JOBS,
            incremental,
        }
    }

    fn canaries_match(&self, other: &Self) -> bool {
        // proven:
        self.version == other.version
            && self.opt_level == other.opt_level
            && self.target == other.target
        // paranoid:
            && self.num_jobs == other.num_jobs
            && self.debug == other.debug
        // NOTE: host is not included, since we can't change it, and stabby says it's paranoid
        // anyways
    }
}

#[derive(Clone, Debug, PartialEq, Eq, Hash, Serialize, Deserialize)]
pub struct PackageName(String);

impl Borrow<str> for PackageName {
    fn borrow(&self) -> &str {
        &self.0
    }
}

#[derive(Clone, Debug, PartialEq, Eq, Hash, Serialize, Deserialize)]
pub struct LibraryName(String);

impl Borrow<str> for LibraryName {
    fn borrow(&self) -> &str {
        &self.0
    }
}

#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
pub struct Crate {
    /// The crate folder in the `source` directory.
    pub source: PathBuf,
    /// The crate folder in the `workspace` directory.
    pub mirror: PathBuf,
    /// The name of the crate.
    pub package_name: PackageName,
    /// The name of the crate's library.
    pub library_name: LibraryName,
    /// The name of the plugin.
    pub plugin_name: PluginName,
    /// If this plugin is a `rubicon` library export.
    pub export: Option<config::plugin::Export>,
}

#[derive(Default)]
pub struct BuildArtifacts {
    pub artifacts: HashMap<PluginName, PathBuf>,
    pub errors: Vec<cargo_metadata::CompilerMessage>,
}

impl BuildArtifacts {
    fn add_artifact(
        &mut self,
        artifact: cargo_metadata::Artifact,
        name_map: &HashMap<&LibraryName, &PluginName>,
    ) {
        let library = LibraryName(artifact.target.name);
        if let [binary] = &artifact.filenames[..] {
            if let Some(plugin) = name_map.get(&library) {
                self.artifacts
                    .insert((*plugin).clone(), binary.as_std_path().to_owned());
            }
        } else {
            warn!(
                "incorrect number of binaries received for library {}. found {}, expected 1",
                library.0,
                artifact.filenames.len()
            );
        }
    }
}

#[derive(Serialize, Deserialize)]
pub struct Workspace {
    path: PathBuf,
    opts: CompileOptions,
    crates: HashMap<PluginName, Crate>,
}

impl Workspace {
    const PROFILE: &'static str = "auditeur";

    pub async fn new(path: impl Into<PathBuf> + Send, opts: CompileOptions) -> Result<Self, Error> {
        let incremental = opts.incremental;
        let mut workspace = Self {
            path: path.into(),
            opts,
            crates: HashMap::new(),
        };
        workspace.init(incremental).await?;
        Ok(workspace)
    }

    pub async fn init(&mut self, incremental: bool) -> Result<bool, Error> {
        let correct_opts = CompileOptions::from_built_info(incremental);
        let opts_are_correct = self.opts.canaries_match(&correct_opts);
        if !opts_are_correct {
            self.opts = correct_opts;
            self.crates.clear();

            warn!("compile options changed - clearing previous build artifacts");

            tokio::fs::remove_dir_all(&self.path).await.or_else(|err| {
                (err.kind() == std::io::ErrorKind::NotFound)
                    .then_some(())
                    .ok_or(err)
            })?;
        }

        tokio::fs::create_dir_all(&self.path).await?;
        self.check_version().await?;

        Ok(opts_are_correct)
    }

    pub async fn new_from_build_info(
        path: impl Into<PathBuf> + Send,
        incremental: bool,
    ) -> Result<Self, Error> {
        let opts = CompileOptions::from_built_info(incremental);
        Self::new(path, opts).await
    }

    pub fn contains(&self, name: &PluginName) -> bool {
        self.crates.contains_key(name)
    }

    pub fn get(&self, name: &PluginName) -> Option<&Crate> {
        self.crates.get(name)
    }

    pub async fn remove(&mut self, name: &PluginName) -> Result<(), Error> {
        if let Some(crt) = self.crates.remove(name) {
            let path = self.path.join(&crt.mirror);
            trace!("removing directory '{}'", path.display());
            tokio::fs::remove_dir_all(&path).await?;
        }
        Ok(())
    }

    async fn check_version(&self) -> Result<(), Error> {
        let found_bytes = tokio::process::Command::new("rustc")
            .arg("--version")
            .output()
            .await?
            .stdout;
        let found = String::from_utf8_lossy(&found_bytes).trim().to_owned();
        let expected = &self.opts.version;
        if &found == expected {
            Ok(())
        } else {
            Err(Error::InvalidRustc {
                found,
                expected: expected.to_owned(),
            })
        }
    }

    async fn init_workspace_manifest(&self) -> Result<(), Error> {
        let path_list = self
            .crates
            .values()
            .filter(|crt| crt.export.is_none())
            .map(|crt| crt.mirror.to_string_lossy())
            .fold('\n'.to_string(), |mut string, path| {
                // NOTE: can't return an error
                let _ = writeln!(string, "  \"{path}\",");
                string
            });
        let patches = self
            .crates
            .values()
            .filter(|crt| crt.export.is_some())
            .map(|crt| (&crt.package_name, &crt.source))
            .fold(String::new(), |mut string, (package, path)| {
                let _ = writeln!(
                    string,
                    "{} = {{ path = \"{}\" }}",
                    &package.0,
                    path.display()
                );
                string
            });
        let opt_level = &self.opts.opt_level;
        let debug = self.opts.debug;
        let profile = Self::PROFILE;
        let incremental = self.opts.incremental;
        let workspace_toml = format!(
            r#"
            [workspace]

            members = [{path_list}]
            resolver = "2"

            [profile.{profile}]
            inherits = "release"
            opt-level = {opt_level}
            debug = {debug}
            incremental = {incremental}

            [patch.crates-io]
            {patches}"#
        );
        tokio::fs::File::create(self.path.join("Cargo.toml"))
            .await?
            .write_all(workspace_toml.as_bytes())
            .await?;
        Ok(())
    }

    pub async fn add(
        &mut self,
        source: PathBuf,
        dependencies: &HashSet<&PluginName>,
        plugin_name: PluginName,
        export: Option<config::plugin::Export>,
        hotreload: bool,
    ) -> Result<PackageName, Error> {
        let manifest = Manifest::load_dir(&source).await?;

        // Get some information from the manifest for bookkeeping.
        let Some(package) = manifest.package.as_ref() else {
            return Err(Error::PackageExpected {
                manifest_path: source.join("Cargo.toml"),
                plugin: plugin_name.clone(),
            });
        };
        let package_name = PackageName(package.name.clone());

        let Some(library) = manifest.lib.as_ref() else {
            return Err(Error::LibraryExpected {
                manifest_path: source.join("Cargo.toml"),
                plugin: plugin_name.clone(),
            });
        };
        let library_name = (library.name)
            .clone()
            .unwrap_or_else(|| package_name.0.replace('-', "_"));
        let library_name = LibraryName(library_name);

        // Copy the manifest to the mirror path.
        let mirror_path = self.path.join(&package_name.0);
        tokio::fs::create_dir_all(&mirror_path).await?;
        let mut manifest = manifest.copy_to_path(&mirror_path);

        // Link dependencies.
        for dependency in dependencies {
            trace!("linking dependency '{dependency}' for '{plugin_name}'");
            let (package, dependency) =
                self.create_dependency_link(&plugin_name, dependency, &manifest)?;
            manifest.dependencies.insert(package.0, dependency);
        }

        let (rubicon_key, rubicon_dep) = Self::rubicon_dependency();
        manifest.dependencies.insert(rubicon_key, rubicon_dep);

        // Ensure the crate is a dylib (useful for hotreloading).
        if export.is_none() && hotreload {
            let lib = manifest.lib.get_or_insert_default();
            if !lib.crate_type.iter().any(|ty| ty == "dylib") {
                lib.crate_type.push("dylib".to_string());
            }
            if let Some(index) = lib.crate_type.iter().position(|ty| ty == "lib") {
                lib.crate_type.remove(index);
            }
        }
        manifest.lints = None;

        // Save all changes made.
        manifest.save().await?;

        let workspace_crate = Crate {
            mirror: mirror_path,
            source: source.clone(),
            package_name: package_name.clone(),
            library_name,
            plugin_name: plugin_name.clone(),
            export,
        };
        self.crates.insert(plugin_name, workspace_crate);

        Ok(package_name)
    }

    fn create_dependency_link(
        &self,
        from: &PluginName,
        to: &PluginName,
        manifest: &Manifest,
    ) -> Result<(PackageName, Dependency), Error> {
        let crt = self
            .crates
            .get(to)
            .ok_or_else(|| Error::PluginDependencyNotFound {
                plugin: from.clone(),
                dependency: to.clone(),
            })?;
        // the previous dependency specification might include features which we want to keep,
        // so we read it from the manifest
        let prev_dependency = manifest
            .dependencies
            .get(&crt.package_name.0)
            .and_then(|dependency| dependency.detail())
            .cloned()
            .unwrap_or_default();
        let dependency = Dependency::Detailed(Box::new(cargo_toml::DependencyDetail {
            path: Some(crt.mirror.to_string_lossy().into_owned()),
            // ensure that no other sources exist
            registry: None,
            registry_index: None,
            git: None,
            branch: None,
            tag: None,
            rev: None,
            // then keep the rest of the config
            ..prev_dependency
        }));
        Ok((crt.package_name.clone(), dependency))
    }

    fn rubicon_dependency() -> (String, Dependency) {
        (
            "rubicon".to_string(),
            Dependency::Detailed(Box::new(cargo_toml::DependencyDetail {
                version: Some("3.0".to_string()),
                features: vec!["import-globals".to_string()],
                ..Default::default()
            })),
        )
    }

    pub async fn compile<'a, F, I>(&'a self, plugins_iter: F) -> Result<BuildArtifacts, Error>
    where
        F: Fn() -> I,
        I: Iterator<Item = &'a PluginName>,
    {
        if plugins_iter().next().is_none() {
            return Ok(BuildArtifacts::default());
        }

        // need to make sure that the workspace manifest is here before building
        self.init_workspace_manifest().await?;

        // only build the plugins that haven't been built yet by specifing their crate names
        let package_specifiers = plugins_iter()
            .filter_map(|plugin| self.crates.get(plugin))
            .flat_map(|package| ["--package", package.package_name.borrow()])
            .map(ToOwned::to_owned);
        let mut build_command = std::process::Command::new("cargo")
            .arg("build")
            .args(package_specifiers)
            // extra rust flags
            .env("RUSTFLAGS", "-C prefer-dynamic")
            // canaries
            .args(["--profile", Self::PROFILE])
            .args(["--target", &self.opts.target])
            .args(["--jobs", &self.opts.num_jobs.to_string()])
            // output
            .arg("--message-format=json-render-diagnostics") // output as json
            .arg("--quiet") // avoid non-json messages
            .arg("--keep-going") // keep going even if one plugin fails to compile
            // run the command at the root of the workspace
            .current_dir(&self.path)
            // pipe the stdout of the build command to this process
            .stdout(Stdio::piped())
            .spawn()?;

        let message_stream = build_command.stdout.take().expect("stdout should be piped");
        // collect the names out here so it can be given to the other thread without references
        // these are used to filter the cargo messages so that they only contain plugin artifacts
        // parse the messages in another thread since cargo_metadata doesn't work with async
        let libraries = plugins_iter()
            .filter_map(|package| self.crates.get(package))
            .map(|crt| crt.library_name.clone())
            .collect();
        let messages: Vec<CargoMessage> =
            crate::spawn_blocking(move || Self::parse_messages(message_stream, &libraries)).await?;
        // wait for the process to finish
        let _exit_code = crate::spawn_blocking(move || build_command.wait()).await?;

        let name_map: HashMap<_, _> = plugins_iter()
            .filter_map(|plugin| self.crates.get(plugin))
            .map(|crt| (&crt.library_name, &crt.plugin_name))
            .collect();

        let mut artifacts = BuildArtifacts::default();
        for message in messages {
            match message {
                CargoMessage::CompilerArtifact(artifact) => {
                    artifacts.add_artifact(artifact, &name_map);
                }
                CargoMessage::CompilerMessage(message) => artifacts.errors.push(message),
                _ => unreachable!(),
            }
        }

        Ok(artifacts)
    }

    fn parse_messages(
        stream: impl Read,
        library_names: &HashSet<LibraryName>,
    ) -> std::io::Result<Vec<CargoMessage>> {
        let reader = std::io::BufReader::new(stream);
        CargoMessage::parse_stream(reader)
            .filter(|message| match message {
                Ok(CargoMessage::CompilerArtifact(artifact))
                    if library_names.contains(&*artifact.target.name) =>
                {
                    true
                }
                Ok(CargoMessage::CompilerMessage(_)) | Err(_) => true,
                _ => false,
            })
            .collect()
    }
}
